isr:
isr: {
          // TODO: Revert — exclude actions from ISR due to @astrojs/vercel bug:
          // ISR entrypoint reconstructs POST body without `duplex: 'half'`, causing a TypeError.
          // Excluding actions from ISR lets them go directly to the serverless function.
          // Remove this once the bug is fixed in Astro/Vercel adapter.
          exclude: [/^\/_actions\/.*/],
        }

isr: {
          expiration: 60 * 60 * 24,
          bypassToken: process.env.ISR_BYPASS_TOKEN,
          // /og.png must stay a plain function: Vercel ISR keys its cache on
          // pathname only, so ?t=/&s=/&k= variants all collapse into one cached
          // PNG and every entity shares the first-rendered card (#651). The
          // normal CDN cache (via the route's s-maxage) keys on the full URL.
          // /reset-password carries a per-user ?token=, and ISR keys on the
          // pathname alone: one cached render (an empty error body, in the
          // 2026-10 outage) was served to every reset link for a day.
          exclude: [
            /^\/api\//,
            /^\/og\.png$/,
            /^\/reset-password\/?$/,
            // Same for every per-user page: the staff dashboard (its
            // logged-out redirect was cached for everyone), invites, and
            // unsubscribe links.
            /^\/admin(\/.*)?$/,
            /^\/invite\/?$/,
            /^\/unsubscribe\/?$/,
          ],
        }

exclude:
/^\/api\//,
/^\/og\.png$/,
/^\/reset-password\/?$/,
// Same for every per-user page: the staff dashboard (its
// logged-out redirect was cached for everyone), invites, and
// unsubscribe links.
/^\/admin(\/.*)?$/,
/^\/invite\/?$/,
/^\/unsubscribe\/?$/,

isr:
isr: {
      expiration: 60 * 60,
      bypassToken: process.env.ISR_REVALIDATION_TOKEN || "",
      // API routes manage their own CDN caching via Cache-Control headers
      exclude: [/^\/api\/.+/],
    }

isr: {
      expiration: 60, // Revalidate pages every 60 seconds
      exclude: ['/api/*', '/profile', '/bookmarks'], // Don't cache user-specific or frequently-updated pages
    }

isr: {
      expiration: 60 * 5,
      bypassToken: env.VERCEL_ISR_BYPASS_TOKEN,
      exclude: [
        '/api/[...path]',           // endpoints (send-mail) — nunca cachear
        '/[lang]/preview/[slug]',   // previews de WordPress — siempre frescos
      ],
    }

isr: {
      // Bypass token for on-demand revalidation
      bypassToken: VERCEL_ISR_BYPASS_TOKEN,
      // Exclude API routes, the actions endpoint and admin pages from ISR.
      //
      // /_actions is not optional and not a nicety: everything the adapter does
      // not exclude is routed to the ISR function, and Vercel keys that cache on
      // path and method alone — the request body is not part of it. So the first
      // POST /_actions/reserve ran, wrote its row and had its `{success: true}`
      // stored; every reserve after that, any item, any visitor, was answered
      // from that entry without the function being invoked at all. The button
      // reported success, nothing reached the database, and a reload showed no
      // reservation. `expiration: false` below means "until revalidated", so
      // that entry never aged out. Cancelling went the same way through
      // /_actions/unreserve.
      exclude: [
        /^\/api\/.*/,
        /^\/_actions(\/.*)?$/,
        /^\/wishlist\/~(\/.*)?$/,
      ],
    }

isr: {
    //   expiration: 60, // 5 minutes
    //   bypassToken: process.env.VERCEL_BYPASS_TOKEN,
    //   exclude: [/^(?!\/(?:medal\/[^\/]+\/?|m\/[^\/]+)$).+/],
    // }

isr: {
      // Revalidate dynamic pages every hour
      expiration: 3600,
      // Search must not be ISR-cached — it varies by ?q= query param
      exclude: ['/search'],
    }

isr: {
          expiration: 60 * 60 * 24,
          bypassToken: process.env.ISR_BYPASS_TOKEN,
          // /og.png must stay a plain function: Vercel ISR keys its cache on
          // pathname only, so ?t=/&s=/&k= variants all collapse into one cached
          // PNG and every entity shares the first-rendered card (#651). The
          // normal CDN cache (via the route's s-maxage) keys on the full URL.
          exclude: [/^\/api\//, /^\/og\.png$/],
        }

isr: {
          expiration: 60 * 60 * 24,
          bypassToken: process.env.ISR_BYPASS_TOKEN,
          // /og.png must stay a plain function: Vercel ISR keys its cache on
          // pathname only, so ?t=/&s=/&k= variants all collapse into one cached
          // PNG and every entity shares the first-rendered card (#651). The
          // normal CDN cache (via the route's s-maxage) keys on the full URL.
          exclude: [/^\/api\//, /^\/og\.png$/],
        }

isr: {
      expiration: 60 * 60 * 12, // 12 hours — at most twice a day on traffic
      exclude: [
        /^\/api\/.+/,
        /^\/admin(\/.*)?$/,
        /^\/workshops\/attend\/.+/,
      ],
    }

isr: {
      // Re-fetch from origin after this many seconds. Master-file updates
      // thus become visible within the window even without a redeploy.
      // Short enough to pick up fresh assessments quickly; long enough
      // that a popular page isn't re-rendered on every request.
      expiration: 60,
      // /api/* are dynamic JSON endpoints with query-param-keyed responses,
      // not page renders. ISR's path-keyed cache + crash-prone wrapper
      // (it returns FUNCTION_INVOCATION_FAILED on routes that do their own
      // streaming/JSON output) does not fit this access pattern. Each route
      // sets its own Cache-Control: see apps/web/src/lib/onchain/error.ts.
      exclude: [/^\/api\//],
    }

isr: {
      bypassToken: process.env.REVALIDATE_SECRET,
      exclude: [/^\/api\/.+/],
      // Safety net for tag-level invalidations that cannot be mapped to
      // concrete paths (header/footer/redirects): stale HTML expires on
      // its own after 5 minutes.
      expiration: 300,
    }

isr: {
      expiration: 60 * 60 * 24, // 24 hours default; per-page revalidate overrides this
      // API routes must run per request: the ISR function only forwards the
      // Astro path param, so query params like ?slug=... get stripped and
      // every slug shares one cached GET response.
      exclude: [/^\/api\//],
    }

isr: {
      expiration: 30, // Cacheia as páginas por 30 segundos na Edge CDN para atualização quase instantânea
      exclude: ["/admin", "/login", "/logout", /^\/admin\/.*/],
    }

isr: {
            // Enable ISR for product pages
            expiration: 60 * 60, // 1 hour
        }

isr: {
      // Genera un token seguro con: openssl rand -base64 32
      bypassToken: process.env.ISR_BYPASS_TOKEN || 'cambiar-este-token-en-produccion-32-caracteres-minimo',
      // Excluir rutas que no deben usar ISR (pero incluir /api/revalidate)
      exclude: []
    }

isr: {
      // Never ISR-cache auth, session, or per-user/dynamic routes — a cached
      // OAuth endpoint returns a stale `state` (→ "state_not_found" on the
      // callback) and a cached /api/auth/get-session leaks/staled sessions.
      exclude: [
        "/generator",
        "/examples",
        "/dashboard",
        "/publish",
        "/customize",
        "/demo",
        "/studio/card",
        "/sign-in",
        "/sign-up",
        /^\/api\/.*/,
        /^\/sorry\/.*/,
      ],
    }

isr: {
      expiration: 60 * 5,
      // The daily-menu endpoint is cheap and date-sensitive: always fresh.
      exclude: [/^\/api\/.+/],
    }

isr: {
      expiration: 60 * 60 * 24 * 7, // 1 week
      // Keep API routes on the plain serverless function so their bespoke
      // stale-while-revalidate headers govern caching and error responses
      // (5xx) are never cached as if they were valid pages.
      exclude: [/^\/api\//],
    }

isr: {
      expiration: 60 * 60,
      bypassToken: process.env.VERCEL_ISR_BYPASS_TOKEN,
      // IMPORTANT: `isr` applies to *every* route that opts out of prerendering,
      // not just the blog. Anything whose response is per-request — authenticated,
      // personalized, or mutating — has to be listed here, or the edge will serve
      // a cached copy and the function (including middleware) won't run at all.
      // Only genuinely public, cacheable pages may be left in: today that's the
      // blog routes — the entire point of enabling ISR — plus the homepage,
      // which renders the same Contentful posts and is revalidated alongside
      // them by /api/revalidate.
      exclude: [
        // Performs the cache invalidation itself; must never be cached.
        "/api/revalidate",
        // Streams a per-user chat response.
        "/api/chat",
        // Preview fragments have their own short Cache-Control TTL.
        /^\/api\/link-preview(\/|$)/,
        // Everything behind Basic Auth. This mirrors PROTECTED in
        // src/middleware.ts — the auth check lives in middleware, which only
        // runs when the function does, so a cached response would bypass it.
        // A pattern (not a path list) so new admin routes are covered too.
        /^\/(admin|api\/admin)(\/|$)/,
      ],
    }

exclude:
// Performs the cache invalidation itself; must never be cached.
"/api/revalidate",
// Streams a per-user chat response.
"/api/chat",
// Preview fragments have their own short Cache-Control TTL.
/^\/api\/link-preview(\/|$)/,
// Everything behind Basic Auth. This mirrors PROTECTED in
// src/middleware.ts — the auth check lives in middleware, which only
// runs when the function does, so a cached response would bypass it.
// A pattern (not a path list) so new admin routes are covered too.
/^\/(admin|api\/admin)(\/|$)/,

isr:
isr: {
      // Safety net: the CMS invalidates pages on demand when it publishes.
      expiration: 60 * 60 * 24 * 7,
      bypassToken: process.env.ISR_BYPASS_TOKEN,
      // Forwards the query string (?email=), which ISR ignores.
      exclude: ['/merci'],
    }

isr: {
			// Cache SSR pages for 60s as safety net.
			// On-demand revalidation busts the cache immediately after edits.
			expiration: 60,
			// On-demand revalidation token (set ISR_BYPASS_TOKEN env var)
			bypassToken: process.env.ISR_BYPASS_TOKEN,
			// Exclude dynamic/auth routes from ISR caching
			exclude: [
				/^\/api\//,
				/^\/tavern\/edit\//,
				/^\/tavern\/login/,
				/^\/tavern\/library/,
				/^\/tavern\/admin/,
				/^\/tavern\/set-password/,
				/^\/tavern\/scheduling/,
				// Article pages fetch live content from GitHub — must not be cached
				/^\/tavern\/wiki(?:\/|$)/,
				/^\/studio\/blog\//,
			],
		}

isr: {
          // TODO: Revert — exclude actions from ISR due to @astrojs/vercel bug:
          // ISR entrypoint reconstructs POST body without `duplex: 'half'`, causing a TypeError.
          // Excluding actions from ISR lets them go directly to the serverless function.
          // Remove this once the bug is fixed in Astro/Vercel adapter.
          exclude: [/^\/_actions\/.*/],
        }

isr: {
            expiration: Number(CACHE_DURATION) || 60 * 60 * 24,
            bypassToken: CACHE_BYPASS_TOKEN,
            exclude: [
                /^\/api\/.+/, // Regular expressions supported since @astrojs/vercel@v8.1.0
            ],
        }

isr: {
      // Writing and blog pages fetch Frequency exports at request time.
      // One hour is fresher than the previous 8-hour full production rebuild,
      // without spending build minutes.
      expiration: 60 * 60,
      ...(process.env.ISR_BYPASS_TOKEN ? { bypassToken: process.env.ISR_BYPASS_TOKEN } : {}),
      exclude: ['/til/board', '/api/revalidate', /^\/api\/.+/],
    }

isr: {
      // Cache all pages for 1 day, revalidate in background
      expiration: 60 * 60 * 24,
    }

isr: {
            bypassToken: process.env.ISR_BYPASS_TOKEN,
            // Without this the adapter never expires an entry, so a 404 cached for a
            // not-yet-published URL would outlive the publish.
            expiration: 3600,
            exclude: [
              /^\/api\/.+/,
              /.*\/filtr.*/, // Exclude any URL containing "/filtr"
              /.*\/filter.*/, // Exclude any URL containing "/filtr"
            ],
          }
